"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[510],{6510:(e,t,i)=>{i.d(t,{LanguageProvider:()=>r,o:()=>l});var s=i(5155),a=i(2115);let n={en:{topbar:{home:"Home",about:"About me",projects:"Projects",skills:"Skills",toggleLabel:"Change language",langShort:"EN"},hero:{tags:["Full-stack","AI","Software"],subtitle:"Building reliable systems and web applications, solving problems and learning new technologies."},ctas:{download:"Download CV",about:"About Me"},stats:[{value:"110+",label:"GitHub Projects",icon:"/icons/github.svg"},{value:"1400+",label:"Commits",icon:"/icons/commit.svg"},{value:"24 / 7",label:"Available via Email",icon:"/icons/email.svg"}],about:{title:"About Me",paragraphs:["My name is Nicolas Audibert and I have been studying software development for 4 years. Passionate about technology from a young age, I discovered computers at the age of 3, then code in middle school by experimenting and learning with friends.","My journey at Epitech allowed me to explore many programming languages such as C, C++, Python, SQL, and TypeScript, as well as multiple fields of computer science: video games, software development, artificial intelligence, web, and cybersecurity, in which I obtained a diploma in my 4th year.","During various internships, I had the opportunity to work on projects involving AI, software, and web development, strengthening my versatility and adaptability.","Alongside my studies, I cultivate passions linked to technology, creativity, and discipline. I ride motorcycles and play airsoft, which build rigor, strategy, and teamwork. I am also interested in photography and video, drones, and music, especially drums and piano, practices that enhance my creativity and precision.","With more than 100 projects completed in academic and professional settings, I have developed solid experience in programming and organization, both independently and in teams. Curious, rigorous, and motivated, I constantly seek to deepen my skills and take on new technical challenges."],seeMore:"See more",seeLess:"See less"},experience:{title:"Experiences",items:[{title:"AI Developer — Enedis (Internship)",date:"Mar 2025 - Jul 2025 \xb7 Marseille \xb7 On-site",desc:"Aerial object detection. Semantic generation of graph nodes.",skills:"Skills: Artificial Intelligence (AI), Python",file:"/files/Stage_Enedis_Nicolas_Audibert.pdf"},{title:"Full Stack Developer — NFT box collections (Internship)",date:"Oct 2024 - Mar 2025 \xb7 Marseille \xb7 On-site",desc:"Created dashboards, integrated automated mailing, improved the existing site.",skills:"Skills: Next.js, Firebase, and more",file:"/files/Stage_NFT_Box_Collections_Nicolas_Audibert.pdf"},{title:"Full Stack Developer — La Bo\xeete Immo (Internship)",date:"Jul 2023 - Dec 2023 \xb7 Hy\xe8res \xb7 On-site",desc:"Resolved support tickets, delivered functional evolutions, optimized the user experience on Hektor.",skills:"Skills: PHP, Postman, MySQL, and more",file:"/files/Stage_La_Boite_Immo_Nicolas_Audibert.pdf"}]},footer:{contact:"Contact",social:"Social",navigation:"Navigation",home:"Home",about:"About",projects:"Projects",skills:"Skills",rights:"All rights reserved."},carousel:{itemLabel:"Item",reset:"Reset View",tooSmall:"TOO SMALL"},competences:{title:"Technologies Used"},skills:{title:"Skills",categories:[{title:"AI & Data",skills:["AI","LLM Integration","Python (NumPy/Pandas)","Data Visualization"]},{title:"Cybersecurity Tools",skills:["Nmap","Burp Suite","Wireshark","OWASP ZAP","Metasploit","Autopsy"]},{title:"Frontend",skills:["React.js","Next.js","TypeScript","JavaScript","Tailwind CSS","Material-UI"]},{title:"Backend & APIs",skills:["Express.js","Node.js","REST APIs","GraphQL","Postman"]},{title:"Cloud & Hosting",skills:["Firebase","Vercel","Docker","CI/CD"]},{title:"Languages",skills:["Python","TypeScript","JavaScript","C","C++","PHP"]},{title:"Databases",skills:["SQL","SQLite","Firestore","MongoDB"]},{title:"Tools & IDEs",skills:["GitHub","VS Code","Postman","Linux","Windows"]},{title:"Productivity",skills:["Microsoft Office","Notion","Trello","GitHub Projects"]}]},projects:{area:{title:"Area",paragraphs:["AREA (Application for Remote Execution of Actions) is a project developed as part of the Epitech curriculum. It is a web and mobile application that automates tasks by connecting different services together.","Inspired by platforms like IFTTT (If This Then That) and Zapier, AREA lets users create actions that trigger in response to specific events, from both a web browser and a mobile app."]},cryptobottle:{title:"Cryptobottle",paragraphs:["Cryptobottle is a web platform that combines the wine world and blockchain. Users can create, buy, and collect virtual bottles containing cryptocurrencies and real-world benefits (promotions, offers, discounts). The project blends investment, digital art, and a marketplace.","I developed a configurable dynamic pop-up system and a complete admin dashboard, and I contributed to the overall design and styling of the application."]},forensic:{title:"Forensic",paragraphs:["During my fourth year, I completed a dual degree in cybersecurity at Epitech Brussels, supervised by industry professionals. This program let me deepen my knowledge of Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis, and Architecture & Cloud Security.","As part of this program, I carried out a forensic project that involved analyzing a disk image and a provided network trace, extracting relevant data, and writing a report detailing the investigation's conclusions."]},myHunter:{title:"MyHunter",paragraphs:["MyHunter is a cops-and-robbers game where the player acts as a police officer tasked with eliminating thieves while avoiding civilians. Gameplay is based on a shooting system that requires speed, accuracy, and timing, with penalties for mistakes.","The game features three types of characters: thieves, who score points when neutralized, and civilians, men or women, who must be avoided at all costs. Hitting a civilian results in a heavy point loss."]},pentest:{title:"Pentest",paragraphs:["During my Epitech studies, I completed several pentest projects on TryHackMe, complemented by self-directed cybersecurity training. These experiences strengthened my skills in vulnerability analysis, penetration testing, and technical report writing.","During my fourth year, I completed a dual degree in cybersecurity at Epitech Brussels, supervised by industry professionals. This program let me deepen my knowledge of Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis, and Architecture & Cloud Security."]},rtype:{title:"RType",paragraphs:["R-Type is a side-scrolling shooter where the player pilots a spaceship against waves of enemies. Gameplay relies on dodging, strategic weapon use, and the Force module, which is essential for offense and defense.","We developed a multiplayer version of R-Type, including match creation, lobbies to bring players together, and a lag-compensation system. These features enabled a smooth, synchronized experience even with varied network connections."]}}},fr:{topbar:{home:"Accueil",about:"\xc0 propos",projects:"Projets",skills:"Comp\xe9tences",toggleLabel:"Changer de langue",langShort:"FR"},hero:{tags:["Full-stack","IA","Logiciel"],subtitle:"Construire des syst\xe8mes fiables et des applications web, r\xe9soudre des probl\xe8mes et apprendre de nouvelles technologies."},ctas:{download:"T\xe9l\xe9charger le CV",about:"\xc0 propos"},stats:[{value:"110+",label:"Projets GitHub",icon:"/icons/github.svg"},{value:"1400+",label:"Commits",icon:"/icons/commit.svg"},{value:"24 / 7",label:"Disponible par email",icon:"/icons/email.svg"}],about:{title:"\xc0 propos de moi",paragraphs:["Je m'appelle Nicolas Audibert et je suis \xe9tudiant en d\xe9veloppement informatique depuis maintenant 4 ans. Passionn\xe9 par l'informatique depuis mon plus jeune \xe2ge, j'ai d\xe9couvert le monde des ordinateurs d\xe8s l'\xe2ge de 3 ans, puis celui du code au coll\xe8ge, en exp\xe9rimentant et en apprenant avec des amis.","Mon parcours \xe0 Epitech m'a permis d'explorer de nombreux langages de programmation tels que C, C++, Python, SQL et TypeScript, ainsi que plusieurs domaines de l'informatique : le jeu vid\xe9o, le d\xe9veloppement logiciel, l'intelligence artificielle, le web et la cybers\xe9curit\xe9, dans laquelle j'ai obtenu un dipl\xf4me en 4ᵉ ann\xe9e.","Au cours de diff\xe9rents stages, j'ai eu l'opportunit\xe9 de travailler sur des projets vari\xe9s touchant \xe0 l'IA, au software et au d\xe9veloppement web, renfor\xe7ant ainsi ma polyvalence et ma capacit\xe9 d'adaptation.","En parall\xe8le de mes \xe9tudes, je nourris plusieurs passions li\xe9es \xe0 la technologie, \xe0 la cr\xe9ativit\xe9 et \xe0 la discipline. Je pratique la moto et l'airsoft, qui d\xe9veloppent rigueur, strat\xe9gie et esprit d'\xe9quipe. Je m'int\xe9resse \xe9galement \xe0 la photo et \xe0 la vid\xe9o, aux drones, ainsi qu'\xe0 la musique, notamment la batterie et le piano, des pratiques qui renforcent ma cr\xe9ativit\xe9 et ma pr\xe9cision.","Avec plus de 100 projets r\xe9alis\xe9s en milieu acad\xe9mique et professionnel, j'ai d\xe9velopp\xe9 une solide exp\xe9rience en programmation, mais aussi en organisation, aussi bien en autonomie qu'en travail d'\xe9quipe. Curieux, rigoureux et motiv\xe9, je cherche constamment \xe0 approfondir mes comp\xe9tences et \xe0 relever de nouveaux d\xe9fis techniques."],seeMore:"Voir plus",seeLess:"Voir moins"},experience:{title:"Exp\xe9riences",items:[{title:"D\xe9veloppeur IA — Enedis (Stage)",date:"mars 2025 - juil. 2025 \xb7 Marseille \xb7 Sur site",desc:"D\xe9tection d'objets a\xe9riens. G\xe9n\xe9ration s\xe9mantique de nœuds de graphes.",skills:"Comp\xe9tences : Intelligence artificielle (IA), Python",file:"/files/Stage_Enedis_Nicolas_Audibert.pdf"},{title:"D\xe9veloppeur Full Stack — NFT box collections (Stage)",date:"oct. 2024 - mars 2025 \xb7 Marseille \xb7 Sur site",desc:"Cr\xe9ation de dashboards, int\xe9gration de mailing automatique, am\xe9liorations du site existant.",skills:"Comp\xe9tences : Next.js, Firebase, et plus",file:"/files/Stage_NFT_Box_Collections_Nicolas_Audibert.pdf"},{title:"D\xe9veloppeur Full Stack — La Bo\xeete Immo (Stage)",date:"juil. 2023 - d\xe9c. 2023 \xb7 Hy\xe8res \xb7 Sur site",desc:"R\xe9solution de tickets SAV, \xe9volutions fonctionnelles, optimisation de l'exp\xe9rience utilisateur sur Hektor.",skills:"Comp\xe9tences : PHP, Postman, MySQL, et plus",file:"/files/Stage_La_Boite_Immo_Nicolas_Audibert.pdf"}]},footer:{contact:"Contact",social:"R\xe9seaux",navigation:"Navigation",home:"Accueil",about:"\xc0 propos",projects:"Projets",skills:"Comp\xe9tences",rights:"Tous droits r\xe9serv\xe9s."},carousel:{itemLabel:"\xc9l\xe9ment",reset:"R\xe9initialiser la vue",tooSmall:"\xc9cran trop petit"},competences:{title:"Technologies utilis\xe9es"},skills:{title:"Comp\xe9tences",categories:[{title:"IA & Donn\xe9es",skills:["IA","Int\xe9gration LLM","Python (NumPy/Pandas)","Visualisation de donn\xe9es"]},{title:"Outils Cybers\xe9curit\xe9",skills:["Nmap","Burp Suite","Wireshark","OWASP ZAP","Metasploit","Autopsy"]},{title:"Frontend",skills:["React.js","Next.js","TypeScript","JavaScript","Tailwind CSS","Material-UI"]},{title:"Backend & APIs",skills:["Express.js","Node.js","API REST","GraphQL","Postman"]},{title:"Cloud & H\xe9bergement",skills:["Firebase","Vercel","Docker","CI/CD"]},{title:"Langages",skills:["Python","TypeScript","JavaScript","C","C++","PHP"]},{title:"Bases de donn\xe9es",skills:["SQL","SQLite","Firestore","MongoDB"]},{title:"Outils & IDEs",skills:["GitHub","VS Code","Postman","Linux","Windows"]},{title:"Productivit\xe9",skills:["Microsoft Office","Notion","Trello","GitHub Projects"]}]},projects:{area:{title:"Area",paragraphs:["AREA (Application for Remote Execution of Actions) est un projet d\xe9velopp\xe9 dans le cadre du cursus Epitech. Il s'agit d'une application disponible en version web et mobile permettant d'automatiser des t\xe2ches en connectant diff\xe9rents services entre eux.","Inspir\xe9e par des plateformes comme IFTTT (If This Then That) et Zapier, AREA permet aux utilisateurs de cr\xe9er des actions qui se d\xe9clenchent en r\xe9ponse \xe0 des \xe9v\xe9nements sp\xe9cifiques, aussi bien depuis un navigateur web que depuis une application mobile."]},cryptobottle:{title:"Cryptobottle",paragraphs:["Cryptobottle est une plateforme web qui allie univers viticole et blockchain. Les utilisateurs peuvent cr\xe9er, acheter et collectionner des bouteilles virtuelles contenant des cryptomonnaies et des avantages r\xe9els (promotions, offres, remises). Le projet m\xeale investissement, art digital et marketplace.","J'y ai d\xe9velopp\xe9 un syst\xe8me de pop-up dynamique configurable ainsi qu'un dashboard d'administration complet, et particip\xe9 \xe0 la conception et au style global de l'application."]},forensic:{title:"Forensic",paragraphs:["Lors de ma quatri\xe8me ann\xe9e, j'ai suivi un double dipl\xf4me en cybers\xe9curit\xe9 \xe0 Epitech Bruxelles, encadr\xe9 par des professionnels du secteur. Cette formation m'a permis d'approfondir mes connaissances en Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis et Architecture & Cloud Security.","Dans le cadre de cette formation, j'ai r\xe9alis\xe9 un projet de forensic consistant \xe0 analyser une image disque ainsi qu'une trame r\xe9seau fournies, extraire des donn\xe9es pertinentes et r\xe9diger un rapport d\xe9taillant les conclusions de l'enqu\xeate."]},myHunter:{title:"MyHunter",paragraphs:["MyHunter est un jeu police/voleur dans lequel le joueur incarne un policier charg\xe9 d'\xe9liminer des voleurs tout en \xe9vitant les civils. Le gameplay repose sur un syst\xe8me de tir demandant rapidit\xe9, pr\xe9cision et respect du timing, avec des p\xe9nalit\xe9s appliqu\xe9es en cas d'erreur.","Le jeu met en sc\xe8ne trois types de personnages : les voleurs, qui rapportent des points lorsqu'ils sont neutralis\xe9s, et les civils, hommes ou femmes, qu'il faut \xe9viter \xe0 tout prix. Toucher un civil entra\xeene une lourde perte de points."]},pentest:{title:"Pentest",paragraphs:["Au cours de mon cursus \xe0 Epitech, j'ai r\xe9alis\xe9 plusieurs projets de pentest sur TryHackMe, compl\xe9t\xe9s par des entra\xeenements en cybers\xe9curit\xe9 effectu\xe9s en autonomie. Ces exp\xe9riences m'ont permis de renforcer mes comp\xe9tences en analyse de vuln\xe9rabilit\xe9s, tests d'intrusion et r\xe9daction de rapports techniques.","Lors de ma quatri\xe8me ann\xe9e, j'ai suivi un double dipl\xf4me en cybers\xe9curit\xe9 \xe0 Epitech Bruxelles, encadr\xe9 par des professionnels du secteur. Cette formation m'a permis d'approfondir mes connaissances en Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis et Architecture & Cloud Security."]},rtype:{title:"RType",paragraphs:["R-Type est un jeu de tir \xe0 d\xe9filement horizontal dans lequel le joueur pilote un vaisseau spatial affrontant des vagues d'ennemis. Le gameplay repose sur l'esquive, l'utilisation strat\xe9gique des armes et du module Force, essentiel pour attaquer et se d\xe9fendre.","Nous avons d\xe9velopp\xe9 une version multijoueur de R-Type, int\xe9grant la cr\xe9ation de parties, des lobbies pour r\xe9unir les joueurs et un syst\xe8me de lag compensation. Ces fonctionnalit\xe9s ont permis une exp\xe9rience fluide et synchronis\xe9e, m\xeame avec des connexions r\xe9seau vari\xe9es."]}}}},o=(0,a.createContext)(null);function r(e){let{children:t}=e,[i,r]=(0,a.useState)("en");(0,a.useEffect)(()=>{let e=window.localStorage.getItem("lang");("en"===e||"fr"===e)&&r(e)},[]),(0,a.useEffect)(()=>{window.localStorage.setItem("lang",i)},[i]);let l=()=>r(e=>"en"===e?"fr":"en"),c=(0,a.useMemo)(()=>({language:i,copy:n[i],toggleLanguage:l,setLanguage:r}),[i]);return(0,s.jsx)(o.Provider,{value:c,children:t})}function l(){let e=(0,a.useContext)(o);if(!e)throw Error("useLanguage must be used within a LanguageProvider");return e}}}]);